from functools import wraps
def keep_name(func):
    @wraps(func)
    def wrapper():
        return func()
    return wrapper
@keep_name
def hello():
    return "hi"
print(hello.__name__)

def repeat(n):
    def deco(func):
        def wrapper():
            return func() * n
        return wrapper
    return deco
@repeat(3)
def ab():
    return "ab"
print(ab())

