from functools import lru_cache
@lru_cache
def fib(n):
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)
print(fib(10))

def times(n):
    def deco(func):
        def wrapper():
            return func() * n
        return wrapper
    return deco
@times(5)
def four():
    return 4
print(four())

